import{z as i,x as s,o as e,c as l,q as A,j as n,D as a,d as o,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"教育经济学收束","description":"","frontmatter":{"title":"教育经济学收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-map.md","filePath":"econ/ed2-map.md","lastUpdated":1791063341000}'),d={name:"econ/ed2-map.md"};function c(h,E,p,F,m,D){const B=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="教育经济学收束" tabindex="-1">教育经济学收束 <a class="header-anchor" href="#教育经济学收束" aria-label="Permalink to &quot;教育经济学收束&quot;">​</a></h1><div class="epigraph"><p>教育经济学教给决策者的第一课是：别用平均数做预算——平均投入近乎无效，边际的孩子才值得花钱。</p><footer>—— 据 Hanushek, Economic Journal 2003；Chetty, Friedman and Rockoff, QJE 2014 整理</footer></div><p><a href="/econ/ed2-education-finance">上一课</a>把钱接进了预算与公式，本课程到此收束。剩下的事是把七课的骨架重走一遍，抽出反复出现的三条口径，并交代这门手艺在更大地图上的去向。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>课程从<a href="/econ/ed2-production-deep">教育生产函数的深化</a>起笔：存量记账的增值函数、分数与收入两本产出账、以及「平均投入无效、边际投入有效」的分布读数。随后两条治理线接手——<a href="/econ/ed2-teacher-incentives">教师激励</a>问课堂里的质量从哪来（尾部筛选、绩效工资、执行出勤），<a href="/econ/ed2-school-choice">学校选择与竞争</a>问学校间的市场会不会变好（分拣吞掉竞争，投入组合救回特许校）。需求侧是<a href="/econ/ed2-higher-ed">高等教育经济学</a>：溢价、完成率与信贷约束构成十八岁的决策。<a href="/econ/ed2-skill-formation">技能形成的一生</a>把时间轴拉直：自生产与动态互补让早期投入成为乘数。<a href="/econ/ed2-education-finance">教育财政</a>最后把管道接上：公式决定钱落在哪一层、哪一个孩子身上。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条口径贯穿全部七课，收束在这里钉死。第一，平均与边际：输入端平均效应近零（Hanushek 元统计、智利全民券），但在被约束的边际上效应可观——STAR 的小班、改革年代的财政美元、缺勤的相机。<span class="marginnote">直觉类比：「平均投入无效」像给全班每人都发一副更贵的眼镜——多数人视力正常，钱撒在了不需要的人身上；「边际有效」是把眼镜递给真正近视的那几个。钱有没有用，取决于它落在分布的哪一段。</span>预算问题从来是「给谁、在哪一年、哪种约束下」的问题，不是「钱有没有用」的问题。第二，代理与产出：分数会衰减，收入不衰减；教师增值预测成年结果（Chetty–Friedman–Rockoff 2014），佩里的 IQ 红利消失而收入红利留存（Heckman 等 2010）。拿分数当终点评估教育，等于用会衰减的坐标去度量不衰减的向量。第三，个体与均衡：个体回报高估社会回报——溢价会被队列扩招压回，择校会把不平等重新排版，羊皮纸里藏着社会不必支付的信号成本。<span class="marginnote">常见误区：把「读大学的人挣得多」直接加总成「社会应补贴更多人读大学」。个体回报里含排序的信号成分——全社会一起多读一年，名次没变，溢价被重新定价；个体账本与社会账本不能混抄。</span>每做一次政策推断，先问自己在哪一条口径上站位。</p>',7)),(e(),n(r,null,{default:a(()=>[t(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E7%94%9F%E4%BA%A7%E5%87%BD%E6%95%B0%EF%BC%9A%E5%AD%98%E9%87%8F%E8%AE%B0%E8%B4%A6%22%5D%20--%3E%20TE%5B%22%E6%95%99%E5%B8%88%E6%BF%80%E5%8A%B1%EF%BC%9A%E8%B4%A8%E9%87%8F%E6%B2%BB%E7%90%86%22%5D%0A%20%20PF%20--%3E%20CH%5B%22%E6%8B%A9%E6%A0%A1%E7%AB%9E%E4%BA%89%EF%BC%9A%E5%88%86%E6%8B%A3%E4%B8%8E%E7%94%9F%E4%BA%A7%22%5D%0A%20%20TE%20--%3E%20HE%5B%22%E9%AB%98%E7%AD%89%E6%95%99%E8%82%B2%EF%BC%9A%E6%BA%A2%E4%BB%B7%E4%B8%8E%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CH%20--%3E%20HE%0A%20%20HE%20--%3E%20SF%5B%22%E6%8A%80%E8%83%BD%E5%BD%A2%E6%88%90%E7%9A%84%E4%B8%80%E7%94%9F%EF%BC%9A%E5%8A%A8%E6%80%81%E4%BA%92%E8%A1%A5%22%5D%0A%20%20SF%20--%3E%20FI%5B%22%E6%95%99%E8%82%B2%E8%B4%A2%E6%94%BF%EF%BC%9A%E7%AE%A1%E9%81%93%E4%B8%8E%E5%85%AC%E5%BC%8F%22%5D%0A%20%20FI%20--%3E%20PF%0A%20%20SF%20--%3E%20G%5B%22%E5%AE%8F%E8%A7%82%E5%9B%9E%E5%A3%B0%EF%BC%9A%E8%AE%A4%E7%9F%A5%E6%8A%80%E8%83%BD%E4%B8%8E%E5%A2%9E%E9%95%BF%22%5D%0A%20%20FI%20--%3E%20DC%5B%22%E5%86%B3%E7%AD%96%E5%8F%A3%E5%BE%84%EF%BC%9A%E9%A2%84%E7%AE%97%E4%B8%8E%E8%BE%B9%E9%99%85%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这套口径为什么能迁出教育现场。向宏观走：各国认知技能的差异对应长期增长率的系统性差异，Hanushek–Woessmann 2015 的折算约是 1 个标准差的成绩差对应 2 个百分点的长期增长差——<span class="marginnote">数字实例：1 个标准差的成绩差大约相当于泰国与日本之间的平均分差距；换成增长是每年 2 个百分点，四十年复利累积下来，经济总量能差出一倍以上——微观分数之所以「贵」到宏观，靠的就是这种复利。</span>微观的生产函数加总成了<a href="/econ/endogenous-growth">内生增长：人力资本与 R&amp;D</a>里的人力资本引擎。向方法走：本课程的全部证据都挂在准实验的纪律上，评估的终点是预算选择而非系数本身，这正是<a href="/econ/pe-decision-target">以决策为目标</a>的口径；识别工具的更新（新的行政数据、机器学习的异质效应）改变的是边际的分辨率，不是三条口径的任何一条。教育的特殊之处在于它同时是投资品、信号与公共品——三条口径就是为了让你在这三重身份之间不再混淆记账。</p><p>评估一个教育主张时，三问就是把主张按口径分拣的分叉图。</p>',3)),(e(),n(r,null,{default:a(()=>[t(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%7B%22%E5%9C%A8%E5%93%AA%E6%9D%A1%E5%8F%A3%E5%BE%84%E4%B8%8A%E7%AB%99%E4%BD%8D%3F%22%7D%20--%3E%20AVG%5B%22%E5%B9%B3%E5%9D%87%E5%AF%B9%E8%BE%B9%E9%99%85%3A%20%E6%95%88%E5%BA%94%E5%8F%AA%E5%9C%A8%E7%BA%A6%E6%9D%9F%E8%BE%B9%E9%99%85%E5%87%BA%E7%8E%B0%22%5D%0A%20%20P%20--%3E%20MEA%5B%22%E4%BB%A3%E7%90%86%E5%AF%B9%E4%BA%A7%E5%87%BA%3A%20%E5%88%86%E6%95%B0%E8%A1%B0%E5%87%8F%2C%20%E6%94%B6%E5%85%A5%E4%B8%8D%E8%A1%B0%E5%87%8F%22%5D%0A%20%20P%20--%3E%20EQ%5B%22%E4%B8%AA%E4%BD%93%E5%AF%B9%E5%9D%87%E8%A1%A1%3A%20%E6%89%A9%E6%8B%9B%E5%8E%8B%E6%BA%A2%E4%BB%B7%2C%20%E4%BF%A1%E5%8F%B7%E6%98%AF%E7%A4%BE%E4%BC%9A%E6%88%90%E6%9C%AC%22%5D%0A%20%20AVG%20--%3E%20BUD%5B%22%E9%A2%84%E7%AE%97%E5%88%A4%E6%96%AD%3A%20%E7%BB%99%E8%B0%81%2F%E5%93%AA%E4%B8%80%E5%B9%B4%2F%E5%93%AA%E7%A7%8D%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20MEA%20--%3E%20BUD%0A%20%20EQ%20--%3E%20BUD%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不掩盖开放问题：增值模型的长期稳定性、绩效激励的规模化衰减、技能形成技术在不同人群的外推、财政公式与居住分拣的均衡互动，都还在被证据追赶。<span class="marginnote">最常犯的误读是把第一课读成「学校无用」：Coleman 报告与 Hanushek 元统计否定的只是可观测投入的平均效应，不是学校——尾部筛选与边际财政都是有效的用钱方式，「无用」与「平均无效」之间隔着整个分布。</span>本课程到此收束：往后遇到任何教育政策的提案，先问三句——边际在谁身上、产出记在哪本账、均衡会不会把个体回报改写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条口径：平均对边际、代理对产出、个体对均衡；每条都有七课内部的证据闭环。</li><li>生产函数按存量记账，教师与择校是治理，高教与技能形成是需求与时间轴，财政是管道。</li><li>宏观回声：1 个标准差认知技能差对应约 2 个百分点的长期增长率差（Hanushek–Woessmann 2015）。</li><li>教育的三重身份——投资、信号、公共品——记账不可混。</li><li>出处：Hanushek, Economic Journal 2003；Chetty, Friedman and Rockoff, QJE 2014；Heckman 等, JPubE 2010；Hanushek and Woessmann, The Knowledge Capital of Nations, 2015。</li></ul>',4))])}const u=i(d,[["render",c]]);export{_ as __pageData,u as default};
